// Usage: npm run hash-password -- "your-new-password"
//
// This generates the hash for the single admin login only. Member
// passwords are hashed the same way (bcryptjs) but generated by the
// app itself — via the admin dashboard's "set password" field or a
// member's own OTP-verified reset — and stored in
// content/credentials.json, not .env.local. This script just prints
// the value to paste into .env.local as ADMIN_PASSWORD_HASH_B64.
//
// It's base64-encoded because bcrypt hashes contain `$`-prefixed
// segments (e.g. $2a$10$...) that Next.js's env-file loader
// (dotenv-expand) mistakes for variable references and silently
// corrupts. Base64-encoding sidesteps that entirely.
const bcrypt = require("bcryptjs");

const password = process.argv[2];
if (!password) {
  console.error('Usage: npm run hash-password -- "your-password"');
  process.exit(1);
}

const hash = bcrypt.hashSync(password, 10);
const b64 = Buffer.from(hash, "utf-8").toString("base64");

console.log("\nPaste into .env.local as ADMIN_PASSWORD_HASH_B64:");
console.log(b64);
